// ---- n8n/codigo/precos.js ----
// Preço por milhão de tokens (US$), entrada e saída. Fontes: tabelas de preços da Anthropic e do Google (nov/2026).
// Gemini: nível gratuito da API, custo zero (há limite de requisições por minuto e por dia).
const PRECOS_POR_MILHAO = {
  "claude-opus-5-5": { entrada: 4, saida: 20 },
  "claude-sonnet-5-5": { entrada: 2, saida: 10 },
  "claude-fable-5-2": { entrada: 8, saida: 40 },
  "claude-haiku-5-5": { entrada: 0.1, saida: 0.5 },
  "gemini-3.8-flash": { entrada: 0, saida: 0 },
  "gemini-3.5-flash-lite": { entrada: 0, saida: 0 },
};

function custoUsd(modelo, tokensEntrada, tokensSaida) {
  const p = PRECOS_POR_MILHAO[modelo];
  if (!p) return null;
  return (tokensEntrada * p.entrada + tokensSaida * p.saida) / 1e6;
}

if (typeof module !== "undefined") module.exports = { custoUsd, PRECOS_POR_MILHAO };

// ---- n8n/codigo/triagem-comum.js ----
// Partes da triagem que não dependem do provedor de IA.
const CATEGORIAS = ["bug_produto", "teste_instavel", "teste_quebrado"];

const ESQUEMA_TRIAGEM = {
  type: "object",
  properties: {
    categoria: { type: "string", enum: CATEGORIAS },
    confianca: { type: "number" },
    resumo: { type: "string" },
    passos: { type: "array", items: { type: "string" } },
    esperado: { type: "string" },
    obtido: { type: "string" },
    causaProvavel: { type: "string" },
    sugestaoCorrecao: { type: "string" },
  },
  required: ["categoria", "confianca", "resumo", "passos", "esperado", "obtido", "causaProvavel", "sugestaoCorrecao"],
  additionalProperties: false,
};

function textoDaFalha(falha) {
  return [
    `Teste: ${falha.titulo}`,
    `Arquivo: ${falha.arquivo}${falha.linha ? `, linha ${falha.linha}` : ""}`,
    `Tentativas: ${falha.tentativas}`,
    `Passou numa nova tentativa: ${falha.passouNaNovaTentativa ? "sim" : "não"}`,
    `Duração total: ${falha.duracaoMs} ms`,
    "",
    "Mensagem de erro:",
    falha.erro,
    "",
    "Stack:",
    falha.stack || "(sem stack)",
    "",
    "Trecho do código do teste:",
    falha.trechoCodigo || "(código não disponível)",
    "",
    falha.printBase64 ? "O print da tela no momento da falha está anexado." : "Não há print desta falha.",
  ].join("\n");
}

/** Converte o texto JSON devolvido pela IA em triagem, ou explica por que não deu. */
function lerTriagemDoTexto(texto) {
  let triagem;
  try {
    triagem = JSON.parse(texto);
  } catch {
    return { triagem: null, erro: "A IA devolveu um JSON inválido." };
  }
  if (!triagem || !CATEGORIAS.includes(triagem.categoria)) {
    return { triagem: null, erro: `A IA devolveu uma categoria inválida: ${triagem?.categoria}` };
  }
  return { triagem, erro: null };
}

/**
 * Texto de erro legível para respostas de erro de Claude ou Gemini, no formato direto da API
 * ou no formato do n8n após esgotar as novas tentativas (mensagem "503 - \"{...json...}\"").
 * Devolve null quando a resposta não é erro.
 */
function descreverErroHttp(r) {
  if (!r || (!r.error && !(r.statusCode >= 400))) return null;
  let erro = r.error || {};
  let status = r.statusCode ?? (typeof erro.status === "number" ? erro.status : undefined) ?? erro.code;
  const embutido = typeof erro.message === "string" && erro.message.match(/^(\d{3}) - ([\s\S]*)$/);
  if (embutido) {
    status = Number(embutido[1]);
    try {
      let corpo = JSON.parse(embutido[2]);
      if (typeof corpo === "string") corpo = JSON.parse(corpo);
      if (corpo && corpo.error) erro = corpo.error;
    } catch {}
  }
  const tipo = erro.type ?? (typeof erro.status === "string" ? erro.status : undefined) ?? "erro";
  const msg = embutido && erro === r.error ? embutido[2] : (erro.message ?? "");
  return `Erro da API (HTTP ${status ?? "?"}): ${tipo}${msg ? ` - ${msg}` : ""}`;
}

if (typeof module !== "undefined") module.exports = { CATEGORIAS, ESQUEMA_TRIAGEM, textoDaFalha, lerTriagemDoTexto, descreverErroHttp };

// ---- n8n/codigo/provedor.js ----
/** Provedor de IA pelo nome do modelo: "gemini-..." usa o Gemini; o resto, o Claude. */
function provedorDoModelo(modelo) {
  return String(modelo || "").startsWith("gemini-") ? "gemini" : "claude";
}

if (typeof module !== "undefined") module.exports = { provedorDoModelo };

// ---- n8n/codigo/montar-requisicao-claude.js ----
// No n8n, triagem-comum.js é concatenado antes deste arquivo; nos testes, vem por require.
const _comumClaude =
  typeof ESQUEMA_TRIAGEM !== "undefined" ? { ESQUEMA_TRIAGEM, textoDaFalha } : require("./triagem-comum.js");

// Modelos com fallback no servidor (beta server-side-fallback-2026-07-01). O Haiku 5.5 não tem.
const MODELOS_COM_FALLBACK = ["claude-opus-5-5", "claude-sonnet-5-5", "claude-fable-5-2"];

/** Corpo do POST /v1/messages (API do Claude) para triar uma falha. */
function montarRequisicaoClaude(falha, { promptSistema, modelo }) {
  const conteudo = [];
  if (falha.printBase64) {
    conteudo.push({ type: "image", source: { type: "base64", media_type: "image/png", data: falha.printBase64 } });
  }
  conteudo.push({ type: "text", text: _comumClaude.textoDaFalha(falha) });
  const corpo = {
    model: modelo,
    max_tokens: 2000,
    system: promptSistema,
    output_config: { effort: "low", format: { type: "json_schema", schema: _comumClaude.ESQUEMA_TRIAGEM } },
    messages: [{ role: "user", content: conteudo }],
  };
  if (MODELOS_COM_FALLBACK.includes(modelo)) corpo.fallbacks = "default";
  return corpo;
}

if (typeof module !== "undefined") module.exports = { montarRequisicaoClaude };

// ---- n8n/codigo/montar-requisicao-gemini.js ----
// No n8n, triagem-comum.js é concatenado antes deste arquivo; nos testes, vem por require.
const _comumGemini =
  typeof ESQUEMA_TRIAGEM !== "undefined" ? { ESQUEMA_TRIAGEM, textoDaFalha } : require("./triagem-comum.js");

/** Corpo do POST models/{modelo}:generateContent (API do Gemini) para triar uma falha. */
function montarRequisicaoGemini(falha, { promptSistema }) {
  const partes = [];
  if (falha.printBase64) partes.push({ inline_data: { mime_type: "image/png", data: falha.printBase64 } });
  partes.push({ text: _comumGemini.textoDaFalha(falha) });
  return {
    systemInstruction: { parts: [{ text: promptSistema }] },
    contents: [{ role: "user", parts: partes }],
    generationConfig: {
      maxOutputTokens: 4000,
      responseMimeType: "application/json",
      responseJsonSchema: _comumGemini.ESQUEMA_TRIAGEM,
      thinkingConfig: { thinkingLevel: "LOW" },
    },
  };
}

if (typeof module !== "undefined") module.exports = { montarRequisicaoGemini };

// ---- n8n/codigo/interpretar-resposta-claude.js ----
// No n8n, precos.js e triagem-comum.js são concatenados antes deste arquivo; nos testes, vêm por require.
const _depsClaude = {
  custoUsd: typeof custoUsd === "function" ? custoUsd : require("./precos.js").custoUsd,
  lerTriagemDoTexto: typeof lerTriagemDoTexto === "function" ? lerTriagemDoTexto : require("./triagem-comum.js").lerTriagemDoTexto,
  descreverErroHttp: typeof descreverErroHttp === "function" ? descreverErroHttp : require("./triagem-comum.js").descreverErroHttp,
};

/**
 * Converte a resposta da API do Claude (ou o erro HTTP) num resultado de triagem.
 * Nunca lança: qualquer problema vira `erroTriagem`, para a execução seguir com as outras falhas.
 */
function interpretarRespostaClaude(respostaHttp, { modelo, inicioMs, fimMs }) {
  const r = respostaHttp || {};
  const tokensEntrada = r.usage?.input_tokens ?? 0;
  const tokensSaida = r.usage?.output_tokens ?? 0;
  const base = {
    triagem: null,
    erroTriagem: null,
    tokensEntrada,
    tokensSaida,
    custoUsd: _depsClaude.custoUsd(modelo, tokensEntrada, tokensSaida), // null = modelo sem preço conhecido
    duracaoTriagemMs: fimMs - inicioMs,
  };
  const falhou = (motivo) => ({ ...base, erroTriagem: motivo });

  const erroHttp = _depsClaude.descreverErroHttp(r);
  if (erroHttp) return falhou(erroHttp);
  if (r.stop_reason === "refusal") return falhou("A IA recusou a triagem desta falha.");
  if (r.stop_reason === "max_tokens") return falhou("Resposta cortada no limite de tokens.");

  const texto = (r.content || []).find((b) => b.type === "text")?.text;
  const { triagem, erro } = _depsClaude.lerTriagemDoTexto(texto);
  return erro ? falhou(erro) : { ...base, triagem };
}

if (typeof module !== "undefined") module.exports = { interpretarRespostaClaude };

// ---- n8n/codigo/interpretar-resposta-gemini.js ----
// No n8n, precos.js e triagem-comum.js são concatenados antes deste arquivo; nos testes, vêm por require.
const _depsGemini = {
  custoUsd: typeof custoUsd === "function" ? custoUsd : require("./precos.js").custoUsd,
  lerTriagemDoTexto: typeof lerTriagemDoTexto === "function" ? lerTriagemDoTexto : require("./triagem-comum.js").lerTriagemDoTexto,
  descreverErroHttp: typeof descreverErroHttp === "function" ? descreverErroHttp : require("./triagem-comum.js").descreverErroHttp,
};

/**
 * Converte a resposta da API do Gemini (ou o erro HTTP) num resultado de triagem.
 * Nunca lança: qualquer problema vira `erroTriagem`. Tokens de pensamento contam como saída.
 */
function interpretarRespostaGemini(respostaHttp, { modelo, inicioMs, fimMs }) {
  const r = respostaHttp || {};
  const uso = r.usageMetadata || {};
  const tokensEntrada = uso.promptTokenCount ?? 0;
  const tokensSaida = (uso.candidatesTokenCount ?? 0) + (uso.thoughtsTokenCount ?? 0);
  const base = {
    triagem: null,
    erroTriagem: null,
    tokensEntrada,
    tokensSaida,
    custoUsd: _depsGemini.custoUsd(modelo, tokensEntrada, tokensSaida), // null = modelo sem preço conhecido
    duracaoTriagemMs: fimMs - inicioMs,
  };
  const falhou = (motivo) => ({ ...base, erroTriagem: motivo });

  const erroHttp = _depsGemini.descreverErroHttp(r);
  if (erroHttp) return falhou(erroHttp);
  if (r.promptFeedback?.blockReason) return falhou(`A IA bloqueou o pedido (${r.promptFeedback.blockReason}).`);

  const candidato = (r.candidates || [])[0];
  if (!candidato) return falhou("A IA não devolveu nenhuma resposta.");
  if (candidato.finishReason && candidato.finishReason !== "STOP") {
    return falhou(`A resposta da IA terminou com ${candidato.finishReason}.`);
  }
  const texto = (candidato.content?.parts || [])
    .filter((p) => !p.thought && typeof p.text === "string")
    .map((p) => p.text)
    .join("");
  const { triagem, erro } = _depsGemini.lerTriagemDoTexto(texto);
  return erro ? falhou(erro) : { ...base, triagem };
}

if (typeof module !== "undefined") module.exports = { interpretarRespostaGemini };

// ---- n8n/codigo/decidir-acao-issue.js ----
/**
 * Decide o que fazer com a issue de uma falha triada.
 * `issuesExistentes`: issues do repositório com o rótulo triagem-ia (abertas e fechadas).
 * `opcoes.listagemFalhou`: a chamada que lista as issues deu erro.
 */
function decidirAcaoIssue(falha, triagem, issuesExistentes, opcoes = {}) {
  if (!triagem || triagem.categoria === "teste_instavel") return { acao: "nenhuma", numero: null };
  // Sem a lista não dá para saber se a issue já existe: criar agora poderia duplicar.
  if (opcoes.listagemFalhou) {
    return { acao: "nenhuma", numero: null, erro: "Não foi possível listar as issues no GitHub; nada foi criado para não duplicar." };
  }
  const marcador = `<!-- triagem-ia:fp=${falha.id} -->`;
  const mesmas = (issuesExistentes || []).filter((i) => (i.body || "").includes(marcador));
  const aberta = mesmas.find((i) => i.state === "open");
  if (aberta) return { acao: "atualizar", numero: aberta.number };
  if (mesmas.length > 0) return { acao: "reabrir", numero: mesmas[0].number };
  return { acao: "criar", numero: null };
}

if (typeof module !== "undefined") module.exports = { decidirAcaoIssue };

// ---- n8n/codigo/renderizar-issue.js ----
function lerOcorrencias(corpo) {
  const m = (corpo || "").match(/<!-- triagem-ia:ocorrencias=(\d+) -->/);
  return m ? Number(m[1]) : 0;
}

const NOME_CATEGORIA = {
  bug_produto: "Bug do produto",
  teste_quebrado: "Teste quebrado",
  teste_instavel: "Teste instável",
};

/** Impede que texto escrito pela IA mencione (e notifique) pessoas ou times no GitHub. */
function semMencoes(texto) {
  return String(texto ?? "").replace(/@(?=[\w-])/g, "@​");
}

/**
 * Título, corpo (Markdown) e rótulos da issue.
 * `ocorrenciasAnteriores` = contador lido da issue existente (0 se nova).
 * `opcoes.prefixoTitulo` e `opcoes.rodape`: textos do projeto (vazios por padrão).
 */
function renderizarIssue(falha, triagemOriginal, execucao, ocorrenciasAnteriores, opcoes = {}) {
  const ocorrencias = (ocorrenciasAnteriores || 0) + 1;
  const triagem = {
    ...triagemOriginal,
    resumo: semMencoes(triagemOriginal.resumo),
    passos: (triagemOriginal.passos || []).map(semMencoes),
    esperado: semMencoes(triagemOriginal.esperado),
    obtido: semMencoes(triagemOriginal.obtido),
    causaProvavel: semMencoes(triagemOriginal.causaProvavel),
    sugestaoCorrecao: semMencoes(triagemOriginal.sugestaoCorrecao),
  };
  const quebrado = triagem.categoria === "teste_quebrado";
  const corpo = [
    `**${NOME_CATEGORIA[triagem.categoria]}** · confiança da IA: ${Math.round(triagem.confianca * 100)}%`,
    "",
    `**Teste:** \`${falha.titulo}\``,
    "",
    "### Passos para reproduzir",
    ...triagem.passos.map((p, i) => `${i + 1}. ${p}`),
    "",
    "### Esperado",
    triagem.esperado,
    "",
    "### Obtido",
    triagem.obtido,
    "",
    "### Causa provável",
    triagem.causaProvavel,
    "",
    quebrado ? "### Correção sugerida para o teste" : "### Sugestão",
    triagem.sugestaoCorrecao,
    "",
    "---",
    `Ocorrências: ${ocorrencias} · Última ocorrência: ${execucao.data} ([execução ${execucao.id}](${execucao.url}), print e trace nos artefatos)`,
    "",
    `> Issue aberta automaticamente pela triagem com IA.${opcoes.rodape ? ` ${opcoes.rodape}` : ""}`,
    "",
    `<!-- triagem-ia:fp=${falha.id} -->`,
    `<!-- triagem-ia:ocorrencias=${ocorrencias} -->`,
  ].join("\n");
  return { titulo: `${opcoes.prefixoTitulo ?? ""}${triagem.resumo}`, corpo, rotulos: ["triagem-ia", triagem.categoria] };
}

if (typeof module !== "undefined") module.exports = { renderizarIssue, lerOcorrencias };

// ---- n8n/codigo/montar-resultado.js ----
/**
 * Resultado final de uma falha, devolvido pelo webhook.
 * `decisao`: item do nó "Decidir ação"; `acaoRealizada`: criada | atualizada | reaberta | nenhuma;
 * `respostaGithub`: corpo da resposta do GitHub (ou null quando não houve chamada).
 */
function montarResultado(decisao, acaoRealizada, respostaGithub) {
  let acaoIssue = acaoRealizada;
  let issueUrl = null;
  let erroIssue = decisao.erroIssue ?? null;
  if (acaoRealizada !== "nenhuma") {
    if (respostaGithub && respostaGithub.html_url) {
      issueUrl = respostaGithub.html_url;
    } else {
      acaoIssue = "nenhuma";
      erroIssue = `Falha ao ${acaoRealizada === "criada" ? "criar" : "alterar"} a issue: ${
        respostaGithub?.error?.message ?? respostaGithub?.message ?? "resposta sem link"
      }`;
    }
  }
  return {
    falhaId: decisao.falha.id,
    titulo: decisao.falha.titulo,
    triagem: decisao.triagem,
    erroTriagem: decisao.erroTriagem,
    acaoIssue,
    issueUrl,
    erroIssue,
    tokensEntrada: decisao.tokensEntrada,
    tokensSaida: decisao.tokensSaida,
    custoUsd: decisao.custoUsd,
    duracaoTriagemMs: decisao.duracaoTriagemMs,
  };
}

if (typeof module !== "undefined") module.exports = { montarResultado };

// ---- nó: Preparar falhas ----
// Nó "Preparar falhas" (uma vez para todos os itens).
// Entrada: corpo do webhook + issues existentes. Saída: um item por falha, com a requisição pronta para a IA escolhida.
const corpo = $("Webhook").first().json.body;
const listagem = $("GitHub: listar issues").all().map((i) => i.json);
const listagemFalhou = listagem.some((i) => i && i.error);
const issuesExistentes = listagem.filter((i) => i && typeof i.number === "number");
const provedor = provedorDoModelo(corpo.modelo);
const montar = provedor === "gemini" ? montarRequisicaoGemini : montarRequisicaoClaude;
const contexto = { execucao: corpo.execucao, repositorio: corpo.repositorio, modelo: corpo.modelo, issue: corpo.issue || {} };
const inicioMs = Date.now();
return (corpo.falhas || []).map((falha) => ({
  json: {
    falha: { ...falha, printBase64: null },
    contexto,
    provedor,
    issuesExistentes,
    listagemFalhou,
    inicioMs,
    requisicao: montar(falha, { promptSistema: corpo.promptSistema, modelo: corpo.modelo }),
  },
}));

// ---- n8n/codigo/precos.js ----
// Preço por milhão de tokens (US$), entrada e saída. Fontes: tabelas de preços da Anthropic e do Google (nov/2026).
// Gemini: nível gratuito da API, custo zero (há limite de requisições por minuto e por dia).
const PRECOS_POR_MILHAO = {
  "claude-opus-5-5": { entrada: 4, saida: 20 },
  "claude-sonnet-5-5": { entrada: 2, saida: 10 },
  "claude-fable-5-2": { entrada: 8, saida: 40 },
  "claude-haiku-5-5": { entrada: 0.1, saida: 0.5 },
  "gemini-3.8-flash": { entrada: 0, saida: 0 },
  "gemini-3.5-flash-lite": { entrada: 0, saida: 0 },
